extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player", player != null, "Nella scena deve esistere il nodo Player"):
		return
	var camera := find_by_name(player, "Camera2D") as Camera2D
	if not check("camera", camera != null, "Player deve avere un nodo figlio Camera2D"):
		return

	check("limit_smoothed", camera.limit_smoothed, "L'ammorbidimento dell'arresto sui limiti deve essere abilitato (limit_smoothed = true)")

	var ground := find_by_name(main, "Ground") as TileMapLayer
	if not check("ground", ground != null, "Nella scena deve esistere il nodo Ground"):
		return

	var rect: Rect2i = ground.get_used_rect()
	var tile_sz: Vector2i = ground.tile_set.tile_size
	var min_x: float = float(rect.position.x * tile_sz.x)
	var min_y: float = float(rect.position.y * tile_sz.y)
	var max_x: float = float(rect.end.x * tile_sz.x)
	var max_y: float = float(rect.end.y * tile_sz.y)

	player.global_position = Vector2(min_x + 32.0, min_y + 32.0)
	await wait_physics_frames(15)
	var center_tl: Vector2 = camera.get_screen_center_position()
	check("corner_tl", center_tl.x >= min_x - 1.0 and center_tl.y >= min_y - 1.0, "La telecamera non deve oltrepassare l'angolo in alto a sinistra della mappa")

	player.global_position = Vector2(max_x - 32.0, max_y - 32.0)
	await wait_physics_frames(15)
	var center_br: Vector2 = camera.get_screen_center_position()
	check("corner_br", center_br.x <= max_x + 1.0 and center_br.y <= max_y + 1.0, "La telecamera non deve oltrepassare l'angolo in basso a destra della mappa")

